  function auditActionLabel(row){const e=row.details?.event||'';if(e==='open-document')return`Consultazione documento · ${row.details?.title||'Documento sanitario'}`;if(e==='open-original')return`Apertura originale · ${row.details?.title||'Documento sanitario'}`;if(e==='download-original')return`Esportazione documento · ${row.details?.title||'Documento sanitario'}`;if(e==='prepare-visit-print')return'Esportazione / stampa · Prepara visita';if(e==='prepare-visit-originals')return'Esportazione originali · Prepara visita';if(e==='health-data-import')return'Importazione dati salute · Monitoraggio';if(e==='dicom-import')return'Importazione · Imaging DICOM';if(e==='dicom-import-error')return'Errore importazione · Imaging DICOM';if(e==='dicom-link-document')return'Collegamento referto · Imaging DICOM';if(e==='fhir-import')return`Importazione FHIR · ${STORE_LABELS[row.store]||row.store}`;if(row.action==='access')return`Consultazione · ${STORE_LABELS[row.store]||row.store}`;if(row.action==='export')return`Esportazione · ${STORE_LABELS[row.store]||row.store}`;if(row.action==='delete')return`Eliminazione · ${STORE_LABELS[row.store]||row.store}`;if(row.action==='bulk-put')return`Aggiornamento multiplo · ${STORE_LABELS[row.store]||row.store}`;return`Modifica · ${STORE_LABELS[row.store]||row.store}`;}
  async function renderAuditLog(){const host=$('#viewContainer');if(!host)return;const all=(await rows('auditLog')).filter(r=>!(r.action==='view'&&r.details?.event==='view-section')).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));host.innerHTML=`<section class="card modern-content-shell lot2-audit-page"><div class="modern-content-head"><div><h2>Registro accessi e modifiche</h2><p>Documenti consultati, modifiche, importazioni ed esportazioni. La semplice navigazione tra pagine non viene registrata.</p></div><span class="badge">${all.length}</span></div>${all.length?`<div class="lot2-audit-list">${all.slice(0,300).map(r=>`<div class="lot2-audit-row"><div><strong>${esc(auditActionLabel(r))}</strong><small>${esc(r.userName||'Utente')} · ${esc(r.deviceName||'Dispositivo')}</small></div><time>${esc(fmtDateTime(r.createdAt))}</time></div>`).join('')}</div>`:'<div class="notice">Nessuna attività rilevante registrata per questo profilo.</div>'}</section>`;}

