  function parseXml(text){const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw new Error('XML non leggibile');const out=[];xml.querySelectorAll('Record,record,measurement,Measurement').forEach(node=>{const attrs={};for(const a of node.attributes||[])attrs[a.name]=a.value;const r=genericRecord({...attrs,type:attrs.type||attrs.metric||node.querySelector('type')?.textContent,value:attrs.value||node.querySelector('value')?.textContent,unit:attrs.unit||node.querySelector('unit')?.textContent,date:attrs.startDate||attrs.date||node.querySelector('date')?.textContent,device:attrs.device||attrs.deviceName||node.querySelector('device')?.textContent,sourceName:attrs.sourceName||node.querySelector('sourceName')?.textContent});if(r)out.push(r);});return out;}
  async function parseHealthFile(file){const text=await file.text();const ext=(file.name.split('.').pop()||'').toLowerCase();if(ext==='csv')return parseCsv(text);if(ext==='xml')return parseXml(text);if(ext==='json'||ext==='fhir')return parseJson(text);try{return parseJson(text);}catch{}try{return parseXml(text);}catch{}throw new Error('Formato non riconosciuto. Usa CSV, JSON, XML o FHIR JSON.');}
  async function openHealthImport(){if(!canEdit())return;modal('Importa dati salute','Importa misurazioni da file esportati da dispositivi, app o sistemi sanitari. La fonte resta sempre visibile.',`<form id="healthImportForm" class="form-grid"><div class="form-group span-2"><label>File dati</label><input id="healthImportFile" type="file" class="form-control" accept=".csv,.json,.xml,.fhir,application/json,application/xml,text/csv" required><small>Formati supportati: CSV, JSON, XML e FHIR JSON.</small></div><div class="form-group"><label>Classificazione della fonte</label><select id="healthSourceClass" class="form-control" required><option value="unverified">Fonte non verificata</option><option value="wellness-consumer">Wellness / consumer</option><option value="medical-device">Dispositivo sanitario certificato / validato</option><option value="clinical-document">Clinico / documentale</option></select></div><div class="form-group"><label>App, dispositivo o sistema</label><input id="healthSourceName" class="form-control" placeholder="Es. smartwatch, software del laboratorio, app salute"></div><label id="healthCertifiedAckWrap" class="check-row span-2 hidden"><input id="healthCertifiedAck" type="checkbox"><span><strong>Confermo che la specifica funzione che ha prodotto questi dati è certificata/validata per questo uso</strong><small>La certificazione riguarda la singola funzione o misurazione, non automaticamente l’intero dispositivo.</small></span></label><div id="healthImportPreview" class="notice span-2">Seleziona un file per verificare le rilevazioni riconosciute.</div><div class="form-actions span-2"><button type="button" class="btn btn-light" id="healthImportCancel">Annulla</button><button type="submit" class="btn btn-primary" id="healthImportSave" disabled>Importa rilevazioni</button></div></form>`);let parsed=[];const fileInput=$('#healthImportFile'),sourceSelect=$('#healthSourceClass'),preview=$('#healthImportPreview'),save=$('#healthImportSave'),ackWrap=$('#healthCertifiedAckWrap'),ack=$('#healthCertifiedAck');const updateAck=()=>{const cert=sourceSelect.value==='medical-device';ackWrap.classList.toggle('hidden',!cert);save.disabled=!parsed.length||(cert&&!ack.checked);};sourceSelect.onchange=updateAck;ack.onchange=updateAck;fileInput.onchange=async()=>{parsed=[];save.disabled=true;const file=fileInput.files?.[0];if(!file)return;try{parsed=await parseHealthFile(file);const counts={};for(const r of parsed)counts[r.type]=(counts[r.type]||0)+1;preview.className='notice success span-2';preview.innerHTML=parsed.length?`<strong>${parsed.length} rilevazioni riconosciute.</strong><br>${Object.entries(counts).map(([k,n])=>`${esc(k)}: ${n}`).join(' · ')}`:'Nessuna rilevazione compatibile trovata nel file.';}catch(error){preview.className='notice warning span-2';preview.textContent=error.message||'File non leggibile';}updateAck();};$('#healthImportCancel').onclick=closeModal;$('#healthImportForm').onsubmit=async e=>{e.preventDefault();if(!parsed.length)return;const sourceClass=sourceSelect.value,sourceName=$('#healthSourceName').value.trim(),file=fileInput.files?.[0];if(sourceClass==='medical-device'&&!ack.checked)return;const stamp=new Date().toISOString();let saved=0;for(const raw of parsed){const row={id:uid('measure'),profileId:profileId(),...raw,sourceClass,sourceApp:raw.sourceApp||sourceName,device:raw.device||sourceName,source:sourceName||raw.sourceApp||raw.device||'Importazione dati salute',importMethod:'windows-health-import',sourceFileName:file?.name||'',importedAt:stamp,sourceCertificationConfirmed:sourceClass==='medical-device',createdAt:stamp,updatedAt:stamp};await DossierDB.put('measurements',row,{details:{event:'health-data-import',sourceClass,sourceFile:file?.name||''}});saved++;}closeModal();await refreshCurrent();toast(`${saved} rilevazioni importate`);};}
  async function enhanceHealthSources(view){if(!String(view).startsWith('monitor-')||view==='monitor-preferences')return;const host=$('#viewContainer');if(view==='monitor-home'){const actions=$('.monitor-home-greeting .row-actions',host);if(actions&&!$('#healthImportBtn')){const btn=document.createElement('button');btn.id='healthImportBtn';btn.type='button';btn.className='btn btn-light';btn.textContent='Importa dati salute';btn.disabled=!canEdit();btn.onclick=openHealthImport;actions.prepend(btn);}if(!$('#lot2HealthImportCard')){const greeting=$('.monitor-home-greeting',host);const card=document.createElement('section');card.id='lot2HealthImportCard';card.className='card lot2-health-import-card';card.innerHTML=`<div><h3>Importa dati salute</h3><p>Importa misurazioni da CSV, JSON, XML o FHIR. Ogni dato mantiene la propria provenienza e viene distinto tra clinico/documentale, dispositivo sanitario certificato o validato, wellness/consumer e fonte non verificata.</p><div class="lot2-source-pills"><span class="badge success">Clinico / documentale</span><span class="badge success">Dispositivo sanitario validato</span><span class="badge">Wellness / consumer</span><span class="badge warning">Fonte non verificata</span></div></div><button class="btn btn-primary" id="healthImportCardBtn" ${canEdit()?'':'disabled'}>Importa dati salute</button>`;greeting?.insertAdjacentElement('afterend',card);$('#healthImportCardBtn',card)?.addEventListener('click',openHealthImport);}}if($('#lot2HealthSourceSection'))return;const all=await rows('measurements'),external=all.filter(x=>x.sourceClass||x.importMethod);if(!external.length)return;const counts={};for(const x of external){const k=x.sourceClass||'unverified';counts[k]=(counts[k]||0)+1;}const section=document.createElement('section');section.id='lot2HealthSourceSection';section.className='card lot2-health-source';section.innerHTML=`<div class="card-title-row"><div><h3>Provenienza dei dati importati</h3><p class="kpi-note">La classificazione riguarda la specifica misurazione. Dati wellness e non verificati restano informativi.</p></div></div><div class="lot2-source-pills">${Object.entries(counts).map(([k,n])=>`<span class="badge ${sourceBadgeClass(k)}">${esc(SOURCE_LABELS[k]||k)} · ${n}</span>`).join('')}</div></section>`;host.appendChild(section);}

  // Archivio locale gestito: DICOM e immagini associate ai referti.
  function ascii(view,start,len){let s='';for(let i=start;i<Math.min(view.byteLength,start+len);i++){const c=view.getUint8(i);if(c)s+=String.fromCharCode(c);}return s.replace(/\0/g,'').trim();}
  const dicomDate=v=>{const s=String(v||'').replace(/[^0-9]/g,'');return s.length>=8?`${s.slice(0,4)}-${s.slice(4,6)}-${s.slice(6,8)}`:String(v||'');};
  const formatBytes=n=>{n=Number(n||0);if(n<1024)return`${n} B`;if(n<1048576)return`${(n/1024).toFixed(1)} KB`;if(n<1073741824)return`${(n/1048576).toFixed(1)} MB`;return`${(n/1073741824).toFixed(2)} GB`;};
  function mediaParams(kind,pid,owner,path=''){const q=new URLSearchParams({kind:String(kind||''),profileId:String(pid||''),ownerId:String(owner||'')});if(path)q.set('path',String(path));return q.toString();}
  async function storeManagedMedia(kind,pid,owner,path,blob){return DossierSecurity.uploadBlob(`/api/media/store?${mediaParams(kind,pid,owner,path)}`,blob,{contentType:blob?.type||'application/octet-stream'});}
  async function getManagedMediaBlob(kind,pid,owner,path){return DossierSecurity.fetchBlob(`/api/media/file?${mediaParams(kind,pid,owner,path)}`);}
  async function deleteManagedMediaOwner(kind,pid,owner){return DossierSecurity.request('/api/media/delete',{method:'POST',body:{kind,profileId:pid,ownerId:owner}}).catch(()=>({ok:false}));}
  async function managedArchiveStatus(){try{return await DossierSecurity.request('/api/media/archive/status');}catch{return{configured:false,available:false,path:''};}}
  async function chooseManagedArchiveRoot(force=false){const current=await managedArchiveStatus();if(!force&&current.configured&&current.available)return current;if(!force&&current.configured&&!current.available){toast('L’Archivio gestito non è disponibile. Seleziona la sua cartella o una nuova destinazione.');}const result=await DossierSecurity.request('/api/media/archive/select',{method:'POST',body:{}});if(result?.cancelled)return null;if(result?.migratedFiles)toast(`Archivio gestito collegato. ${result.migratedFiles} file esistenti copiati nella nuova destinazione; la copia precedente è stata mantenuta per sicurezza.`);else toast('Destinazione Archivio DICOM gestito salvata');return result;}
  async function syncDicomDocumentBacklink(oldDocumentId,newDocumentId,studyId){const update=async(documentId,add)=>{if(!documentId)return;const doc=await DossierDB.get('documents',documentId);if(!doc)return;const ids=new Set((doc.linkedDicomStudyIds||[]).map(String));add?ids.add(String(studyId)):ids.delete(String(studyId));await DossierDB.put('documents',{...doc,linkedDicomStudyIds:[...ids],updatedAt:doc.updatedAt||new Date().toISOString()},{sync:false,details:{event:add?'dicom-backlink-add':'dicom-backlink-remove',studyId}});};if(oldDocumentId&&String(oldDocumentId)!==String(newDocumentId))await update(oldDocumentId,false);if(newDocumentId)await update(newDocumentId,true);}
