  function bestDoc(meta,docs){const ranked=docs.map(d=>({d,s:docScore(meta,d)})).sort((a,b)=>b.s-a.s);return ranked[0]?.s>=85?ranked[0].d:null;}
  function ensureDicomFolderInput(){let input=$('#dicomFolderInput');if(input)return input;input=document.createElement('input');input.id='dicomFolderInput';input.type='file';input.multiple=true;input.setAttribute('webkitdirectory','');input.setAttribute('directory','');input.className='hidden';document.body.appendChild(input);input.onchange=()=>{const items=[...input.files].map(f=>({file:f,relativePath:f.webkitRelativePath||f.name}));if(items.length)analyzeDicomItems(items,input.dataset.storageMode||'managed',null);};return input;}
