  async function saveDicomLink(id,section){if(!canEdit())return;const study=await DossierDB.get('dicomStudies',id);if(!study)return;const select=$(`[data-l2-dicom-doc="${CSS.escape(id)}"]`,section),docId=String(select?.value||''),docs=await rows('documents'),doc=docs.find(d=>String(d.id)===docId),oldDocId=String(study.linkedDocumentId||'');await DossierDB.put('dicomStudies',{...study,linkedDocumentId:docId,linkedDocumentTitle:doc?.title||doc?.originalName||'',updatedAt:new Date().toISOString()},{sync:false,details:{event:'dicom-link-document',documentId:docId}});await syncDicomDocumentBacklink(oldDocId,docId,id);$('#lot2DicomSection')?.remove();await enhanceDocuments();toast(docId?'Referto collegato allo studio DICOM':'Collegamento al referto rimosso');}
  async function exportDicomStudy(id){const row=await DossierDB.get('dicomStudies',id);if(!row)return;if(typeof JSZip==='undefined')return toast('Modulo ZIP non disponibile');const zip=new JSZip(),pg=progressBox('Esportazione DICOM',row.files?.length||0,row.totalBytes||0);let n=0,bytes=0;try{for(const f of row.files||[]){const blob=await fileFromDescriptor(row,f);zip.file(f.relativePath||f.name,blob);n++;bytes+=Number(blob.size||f.size||0);pg.update((n/Math.max(1,row.files.length))*80,'Preparazione originali',n,bytes);}const blob=await zip.generateAsync({type:'blob',compression:'STORE'},m=>pg.update(80+m.percent*.2,'Creazione archivio ZIP',n,bytes));downloadBlob(blob,`DICOM_${(row.studyDescription||row.studyUID||'studio').replace(/[^a-z0-9]+/gi,'_')}.zip`);}catch(e){toast(e.message==='SUPPORTO_NON_DISPONIBILE'?'Collega il dispositivo che contiene le immagini DICOM':'Esportazione DICOM non riuscita');}finally{pg.close();}}
  async function deleteDicomStudy(id){if(!canEdit())return;const row=await DossierDB.get('dicomStudies',id);if(!row)return;const msg=row.storageMode==='external'?'Eliminare il collegamento a questo studio DICOM? I file sul supporto esterno non verranno cancellati.':row.storageMode==='managed'?'Eliminare questo studio e i relativi file dall’Archivio DICOM locale?':'Eliminare questo studio DICOM copiato nel Dossier?';if(!confirm(msg))return;if(row.storageMode==='managed')await deleteManagedMediaOwner('dicom',row.profileId,id);await syncDicomDocumentBacklink(row.linkedDocumentId||'','',id);await DossierDB.del('dicomStudies',id,{sync:false,profileId:profileId(),details:{event:'dicom-delete'}});if(row.storageMode==='external')await DossierDB.del('handles',`dicom:${id}`,{sync:false}).catch(()=>{});$('#lot2DicomSection')?.remove();await enhanceDocuments();toast('Studio DICOM eliminato');}

